import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry min_reduce_kernel(
    .param .u64 param_0,
    .param .u64 param_1,
    .param .u32 param_2,
    .param .u32 param_3,
    .param .u32 param_4
)
{
    .reg .pred %p<3>;
    .reg .s32 %r<20>;
    .reg .s64 %rd<20>;
    .reg .f32 %f<5>;

    ld.param.u64 %rd1, [param_0];
    ld.param.u64 %rd2, [param_1];
    ld.param.u32 %r1, [param_2];
    ld.param.u32 %r2, [param_3];
    ld.param.u32 %r3, [param_4];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;

    mov.u32 %r4, %ctaid.x;
    mov.u32 %r5, %ntid.x;
    mov.u32 %r6, %tid.x;
    mad.lo.s32 %r7, %r4, %r5, %r6;

    setp.ge.s32 %p1, %r7, %r1;
    @%p1 bra DONE;

    div.s32 %r8, %r7, %r3;
    rem.s32 %r9, %r7, %r3;

    mul.lo.s32 %r10, %r2, %r3;
    mul.lo.s32 %r11, %r8, %r10;
    add.s32 %r12, %r11, %r9;

    mul.wide.s32 %rd4, %r12, 4;
    add.s64 %rd5, %rd1, %rd4;

    ld.global.f32 %f1, [%rd5];

    mul.wide.s32 %rd6, %r3, 4;

    mov.s32 %r13, 1;
    mov.s64 %rd8, %rd5;

LOOP_START:
    setp.ge.s32 %p2, %r13, %r2;
    @%p2 bra LOOP_END;

    add.s64 %rd8, %rd8, %rd6;
    ld.global.f32 %f2, [%rd8];
    min.f32 %f1, %f1, %f2;
    add.s32 %r13, %r13, 1;
    bra LOOP_START;

LOOP_END:
    mul.wide.s32 %rd9, %r7, 4;
    add.s64 %rd10, %rd2, %rd9;
    st.global.f32 [%rd10], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("min_reduce_kernel")

class ModelNew(nn.Module):
    """
    Simple model that performs min reduction over a specific dimension
    using a custom PTX kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        ndim = x.dim()
        dim = self.dim if self.dim >= 0 else self.dim + ndim

        sizes = list(x.shape)

        outer_size = 1
        for s in sizes[:dim]:
            outer_size *= s

        reduce_size = sizes[dim]

        inner_size = 1
        for s in sizes[dim + 1:]:
            inner_size *= s

        out_shape = sizes[:dim] + sizes[dim + 1:]
        output = torch.empty(out_shape, dtype=x.dtype, device=x.device)

        total_output = outer_size * inner_size

        block_x = 256
        grid_x = (total_output + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "min_reduce_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x,
                output,
                i32(total_output),
                i32(reduce_size),
                i32(inner_size),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return output

